sys_script.script:
(function executeRule(current, previous) {
  if (!current.application || current.application.nil()) return;
  var app = new GlideRecord("x_2200409_schola_1_scholarship_application");
  if (!app.get(current.application)) return;
  var st = (app.application_status + "").toLowerCase();
  if (st === "approved" || st === "rejected" || st === "cancelled") return;

  var d = new GlideRecord("x_2200409_schola_1_scholarship_documents");
  d.addQuery("application", app.sys_id);
  d.query();
  var docCount = d.getRowCount();
  var hasPending = false;
  while (d.next()) {
    if (d.verification_status != "verified") {
      hasPending = true;
      break;
    }
  }

  if (docCount > 0 && !hasPending) {
    app.application_status = "under_review";
    app.admin_comments = "All supporting documents verified. Ready for Manager Approval.";
    app.update();

    var mgr = new GlideRecord("sys_user");
    if (mgr.get("user_name", "manager.test")) {
      var apprv = new GlideRecord("sysapproval_approver");
      apprv.addQuery("source_table", "x_2200409_schola_1_scholarship_application");
      apprv.addQuery("document_id", app.sys_id);
      apprv.query();
      if (!apprv.hasNext()) {
        apprv.initialize();
        apprv.document_id = app.sys_id;
        apprv.source_table = "x_2200409_schola_1_scholarship_application";
        apprv.sysapproval = app.sys_id;
        apprv.approver = mgr.sys_id;
        apprv.state = "requested";
        var progName = app.scholarship_program.scholarship_name || app.scholarship_program.getDisplayValue();
        apprv.short_description = "Scholarship Approval: " + (app.application_number || app.number) + " - " + app.student.student_name + " (" + progName + ")";
        apprv.insert();
        gs.info("Document verified: Created manager approval request for " + app.application_number);
      }
    }
  } else {
    if (app.application_status != "documents_pending") {
      app.application_status = "documents_pending";
      app.admin_comments = "Documents require verification before approval.";
      app.update();
    }
  }
})(current, previous);
